USER_CHECK = (
    "{col}::text = current_setting('app.user_id', true) "
    "OR current_setting('app.role', true) IN ('admin', 'system')"
)
STAFF = "current_setting('app.role', true) IN ('admin', 'system')"


def apply_security() -> None:
    """Create the RLS-restricted application role and row level security policies."""
    role = settings.app_db_role
    password = settings.app_db_password.replace("'", "''")
    op.execute(
        f"""
        DO $$
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{role}') THEN
                CREATE ROLE {role} LOGIN PASSWORD '{password}' NOSUPERUSER NOBYPASSRLS;
            ELSE
                ALTER ROLE {role} WITH LOGIN PASSWORD '{password}' NOSUPERUSER NOBYPASSRLS;
            END IF;
        END $$;
        """
    )
    op.execute(f"GRANT USAGE ON SCHEMA public TO {role}")
    op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO {role}")
    op.execute(f"GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO {role}")
    op.execute(f"REVOKE ALL ON alembic_version FROM {role}")

    def enable(table: str) -> None:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")

    # users: a person sees and edits only their own row.
    enable("users")
    check = USER_CHECK.format(col="id")
    op.execute(f"CREATE POLICY users_isolation ON users USING ({check}) WITH CHECK ({check})")

    for table in USER_OWNED_TABLES:
        enable(table)
        check = USER_CHECK.format(col="user_id")
        op.execute(f"CREATE POLICY {table}_isolation ON {table} USING ({check}) WITH CHECK ({check})")

    for table in GLOBAL_TABLES:
        enable(table)
        op.execute(f"CREATE POLICY {table}_read ON {table} FOR SELECT USING (true)")
        op.execute(f"CREATE POLICY {table}_write ON {table} FOR ALL USING ({STAFF}) WITH CHECK ({STAFF})")

    for table in PRIVATE_TABLES:
        enable(table)
        op.execute(f"CREATE POLICY {table}_staff ON {table} USING ({STAFF}) WITH CHECK ({STAFF})")
